async (page) => {
  const editor = await page.$('#editor');
  const box = await editor.boundingBox();
  // find start x of line 33 text (approx after gutter)
  const startX = box.x + 78; // approx text start
  const startY = 669; // line 33 y from screenshot
  await page.mouse.move(startX, startY);
  await page.mouse.down();
  // drag below bottom edge and hold to trigger autoscroll
  const belowX = box.x + box.width - 20;
  const belowY = box.y + box.height + 40;
  await page.mouse.move(belowX, belowY, { steps: 5 });
  // hold there for a while, moving slightly to keep triggering mousemove-based autoscroll
  for (let i = 0; i < 40; i++) {
    await page.mouse.move(belowX + (i%2), belowY);
    await page.waitForTimeout(150);
  }
  const result = { scrollTopDuring: editor.scrollTop };
  return result;
}

